from django.db import migrations

BATCH_SIZE = 1000
MESSAGE_MAX_LENGTH = 1000
ERROR_PREFIX = "\nERROR: "  # appended to output_data by MaCantineBaseCommand when the command fails


def copy_command_logs_to_event_logs(apps, schema_editor):
    """
    Copy every CommandLog into an EventLog (category COMMAND), with the same data as the live EventLog
    - trigger: None (unknown: the --trigger option did not exist yet)
    - message: the error (end of output_data), for the failed commands
    - the full output stays on the CommandLog (kept alongside the EventLog)
    - creation_date: the start_date of the command (bulk_update skips auto_now / auto_now_add)
    - idempotent: data["commandlog_id"] keeps track of the rows already copied
    """
    CommandLog = apps.get_model("common", "CommandLog")
    EventLog = apps.get_model("data", "EventLog")

    already_copied_ids = set(
        EventLog.objects.filter(data__has_key="commandlog_id").values_list("data__commandlog_id", flat=True)
    )
    command_logs = CommandLog.objects.exclude(id__in=already_copied_ids).order_by("id").values()

    batch = []
    for command_log in command_logs.iterator(chunk_size=BATCH_SIZE):
        batch.append(command_log)
        if len(batch) >= BATCH_SIZE:
            _copy_batch(EventLog, batch)
            batch = []
    if batch:
        _copy_batch(EventLog, batch)


def _get_message(command_log):
    output = command_log["output_data"] or ""
    if command_log["status"] != "FAILURE" or ERROR_PREFIX not in output:
        return None
    return output.rsplit(ERROR_PREFIX, 1)[1][:MESSAGE_MAX_LENGTH]


def _get_seconds(command_log):
    if not command_log["start_date"] or not command_log["end_date"]:
        return None
    return round((command_log["end_date"] - command_log["start_date"]).total_seconds(), 2)


def _copy_batch(EventLog, command_logs):
    event_logs = EventLog.objects.bulk_create(
        [
            EventLog(
                category="COMMAND",
                name=command_log["command_name"],
                status=command_log["status"],
                data={
                    "args": (command_log["input_data"] or {}).get("args", []),
                    "options": (command_log["input_data"] or {}).get("options", {}),
                    "trigger": None,
                    "seconds": _get_seconds(command_log),
                    "message": _get_message(command_log),
                    "commandlog_id": command_log["id"],
                },
            )
            for command_log in command_logs
        ]
    )
    for event_log, command_log in zip(event_logs, command_logs):
        event_log.creation_date = command_log["start_date"] or command_log["creation_date"]
        event_log.modification_date = command_log["modification_date"]
    EventLog.objects.bulk_update(event_logs, ["creation_date", "modification_date"])


def delete_copied_event_logs(apps, schema_editor):
    EventLog = apps.get_model("data", "EventLog")
    EventLog.objects.filter(data__has_key="commandlog_id").delete()


